        TreeNode current = root;
        while (current != null) {
            if (high < current.val) {
                current = current.left;
            } else if (low > current.val) {
                current = current.right;
            } else {
                return current;
            }
        }
        return null;
    }
}

class Solution {
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        int low = Math.min(p.val, q.val);
        int high = Math.max(p.val, q.val);

        if (high < root.val) {
            return lowestCommonAncestor(root.left, p, q);
        }
        if (low > root.val) {
            return lowestCommonAncestor(root.right, p, q);
        }
        return root;
    }
}

import java.util.*;

class Solution {
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        List<TreeNode> pathToP = pathTo(root, p.val);
        List<TreeNode> pathToQ = pathTo(root, q.val);

        TreeNode answer = root;
        int i = 0;
        while (i < pathToP.size() && i < pathToQ.size() && pathToP.get(i) == pathToQ.get(i)) {
            answer = pathToP.get(i);
            i++;
        }
        return answer;
    }

    private List<TreeNode> pathTo(TreeNode root, int target) {
        List<TreeNode> path = new ArrayList<>();
        TreeNode current = root;
        while (current != null) {
            path.add(current);
            if (target == current.val) {
                break;
            }
            current = target < current.val ? current.left : current.right;
        }
        return path;
    }
}

class Solution {
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        if (root == null || root.val == p.val || root.val == q.val) {
            return root;
        }

        TreeNode left = lowestCommonAncestor(root.left, p, q);
        TreeNode right = lowestCommonAncestor(root.right, p, q);

        if (left != null && right != null) {
            return root;
        }
        return left != null ? left : right;
    }
}
